function wealthDetailRows(pattern){const out=[];sourceSections.filter(s=>pattern.test(String(s.heading||''))).forEach(s=>(s.tables||[]).forEach(rows=>{if(!rows.length)return;const headers=rows[0]||[];rows.slice(1).forEach(row=>{if(!row[0])return;const amount=parseMoney(row[1]);out.push({label:String(row[0]),amount, date:s._date||''})})}));return out}
function investmentBreakdownHtml(w){const equityInvested=sectionMetric(/Angel One equity overview/i,/^Invested value$/i),equityPnl=sectionMetric(/Angel One equity overview/i,/^Overall unrealised P&L$/i);const equityDay=sectionMetric(/Angel One equity overview/i,/^Today's gain$/i);const equitySection=sourceSections.find(x=>/Angel One equity holdings/i.test(String(x.heading||'')));const equityRows=equitySection?(equitySection.tables||[]).flatMap(t=>{const h=(t[0]||[]).map(v=>String(v).toLowerCase());const idx={qty:h.findIndex(v=>v==='qty'||v.includes('quantity')),avg:h.findIndex(v=>v.includes('avg buy')),ltp:h.findIndex(v=>v.includes('ltp')),pnl:h.findIndex(v=>v.includes('p&l'))};return t.slice(1).filter(r=>r[0]&&!/total/i.test(String(r[0]))).map(r=>({name:String(r[0]),qty:String(r[idx.qty]||''),avg:String(r[idx.avg]||''),ltp:String(r[idx.ltp]||''),pnl:String(r[idx.pnl]||'')})).filter(r=>r.qty)}):[];const equityHoldingsHtml=equityRows.length?'<details class="investment-holdings-toggle"><summary>Show '+equityRows.length+' stock / ETF details</summary><div class="investment-holdings investment-holdings-detailed">'+equityRows.map(r=>'<div class="investment-stock-row"><div class="investment-stock-title"><b>'+esc(r.name)+'</b><span>Qty: '+esc(r.qty)+'</span></div><div class="investment-stock-prices"><span><small>Avg buy</small><b>'+esc(r.avg||'—')+'</b></span><span><small>Current LTP</small><b>'+esc(r.ltp||'—')+'</b></span><span><small>P&L</small><b class="'+(/\(|−|-/.test(r.pnl)?'negative':/^[+]/.test(r.pnl)?'positive':'neutral')+'">'+esc(r.pnl||'—')+'</b></span></div></div>').join('')+'</div></details>':'<p class="investment-note">Share quantities were not present in the latest saved source.</p>';const dematSection=sourceSections.find(x=>/Angel One demat holdings/i.test(String(x.heading||'')));const dematQty={};if(dematSection)(dematSection.tables||[]).forEach(t=>t.slice(1).forEach(r=>{if(r[0]&&r[1]&&!/total/i.test(String(r[0])))dematQty[String(r[0]).toLowerCase().trim()]=String(r[1])}));const mfInvested=sectionMetric(/Angel One mutual funds/i,/^Invested value$/i);const mfSection=sourceSections.find(x=>/Angel One mutual funds/i.test(String(x.heading||'')));const mfRows=mfSection?(mfSection.tables||[]).flatMap(t=>t.slice(1).filter(r=>r[0]&&!/portfolio total|invested value/i.test(String(r[0]))).map(r=>({name:String(r[0]),value:parseMoney(r[1])})).filter(r=>r.value!==null)):[];const metalSections=[...sourceSections].sort((a,b)=>String(b._date||'').localeCompare(String(a._date||'')));const quantityRows=metalSections.flatMap(section=>(section.tables||[]).flatMap(t=>{const h=(t[0]||[]).map(v=>String(v).toLowerCase());const qi=h.findIndex(v=>v.includes('quantity'));return qi<0?[]:t.slice(1).filter(r=>r[0]).map(r=>({name:String(r[0]),quantity:String(r[qi]||''),date:String(section._date||'')}))}));const actualGold=quantityRows.find(r=>/paytm gold/i.test(r.name)&&!(/coin/i.test(r.name)));const silverQuantity=quantityRows.find(r=>/paytm silver/i.test(r.name));const coinSection=metalSections.find(x=>/paytm gold coins/i.test(String(x.heading||'')));const coinRow=(coinSection?.tables||[]).flatMap(t=>t.slice(1)).find(r=>/gold coins/i.test(String(r[0]||'')));const goldCoinQuantity=coinRow?String(coinRow[1]||''):'';const usRows=positions.filter(p=>p.category==='INVESTMENT'&&/INDmoney/i.test(String(p.platform_name||''))&&p.record_type!=='US_PORTFOLIO_INR');const indmoneyAggregate=positions.find(p=>p.record_type==='US_PORTFOLIO_INR'&&/INDmoney/i.test(String(p.platform_name||'')))||positions.find(p=>p.record_type==='US_PORTFOLIO_INR');const indmoneyMeta=indmoneyAggregate?.metadata||{};const fxSummary=indmoneyMeta.fx_reconciled_holdings||{};const cashSummary=indmoneyMeta.cash_balance||{};const inrValue=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n||0));const usPortfolioInr=usRows.reduce((n,r)=>n+Number(r.market_value_inr||0),0)||Number(fxSummary.current_value_inr||0);const usInvestedInr=usRows.reduce((n,r)=>n+Number(r.invested_value||0)*Number(r.market_fx_to_inr||0),0)||Number(fxSummary.invested_value_inr||0);const buyingPowerInr=Number(cashSummary.buying_power_inr||0);const indmoneyTotalInr=usPortfolioInr+buyingPowerInr;const fdRows=positions.filter(p=>p.category==='INVESTMENT'&&p.record_type==='FIXED_DEPOSIT'&&p.metadata?.reconciliation_status!=='pending_reconciliation');const fdDetailsHtml=fdRows.length?'<details class="investment-holdings-toggle"><summary>Show '+fdRows.length+' fixed deposit details</summary><div class="investment-holdings">'+fdRows.map(p=>{const m=p.metadata||{};return '<div class="investment-us-row"><span><b>'+esc(p.name||'Fixed deposit')+'</b><small>'+esc(p.institution_name||'Issuer not specified')+' · '+esc(p.platform_name||'Provider not specified')+(m.interest_rate!=null?' · '+esc(m.interest_rate)+'% p.a.':'')+(m.maturity_date?' · Matures '+esc(m.maturity_date):'')+'</small><small>Invested '+money(p.invested_value||0)+'</small></span><b>'+money(p.current_value||0)+'</b></div>'}).join('')+'</div></details>':'<p class="investment-note">Individual FD records are not available in the saved investment positions yet. The consolidated FD balance is shown above.</p>';return '<div class="investment-categories"><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.fixed_deposit||'▤')+'</span><div><b>Fixed deposits</b><small>All providers · consolidated</small></div><strong>'+money(w.fd)+'</strong></div>'+fdDetailsHtml+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.provident_fund||'◎')+'</span><div><b>EPF / EPS · Provident fund</b><small>Combined two-employer passbook balances · displayed date 31 Mar 2027</small></div><strong>'+money(w.pf)+'</strong></div><p class="investment-note">EPF and EPS are shown together as reported in the passbooks. EPS is a pension component, not ordinary withdrawable EPF. The passbook closing date is future-dated relative to the 9 Nov 2026 snapshot, so treat ₹93,726 as the displayed figure, not a verified current valuation.</p></section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.equity||'↗')+'</span><div><b>Equity · Angel One</b><small>Direct stocks and ETFs</small></div><strong>'+money(w.equity)+'</strong></div><div class="investment-category-metrics"><div><small>Invested</small><b>'+money(equityInvested)+'</b></div><div><small>Unrealised P&L</small><b class="'+(equityPnl<0?'negative':'positive')+'">'+money(equityPnl)+'</b></div><div><small>Today’s gain</small><b class="'+(equityDay<0?'negative':'positive')+'">'+money(equityDay)+'</b></div></div>'+equityHoldingsHtml+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.indmoney_us||'＄')+'</span><div><b>INDmoney · US Stocks</b><small>US portfolio · INR display with original USD retained</small></div><strong>'+inrValue(usPortfolioInr)+'</strong></div><div class="investment-category-metrics"><div><small>Holdings · INR reference</small><b>'+inrValue(usPortfolioInr)+'</b></div><div><small>Invested · INR reference</small><b>'+inrValue(usInvestedInr)+'</b></div><div><small>Buying power · cash</small><b>'+inrValue(buyingPowerInr)+'</b></div></div><p class="investment-note">INDmoney account reference total: <b>'+inrValue(indmoneyTotalInr)+'</b>, including buying power. INR is based on the saved reference FX rate, not a broker redemption quote.</p>'+(usRows.length?'<details class="investment-holdings-toggle"><summary>Show '+usRows.length+' US stock / ETF holdings</summary><div class="investment-holdings">'+usRows.map(r=>{const cv=r.metadata?.inr_conversion||{};return '<div class="investment-us-row"><span><b>'+esc(r.name)+'</b><small>'+esc(r.ticker||'')+' · '+esc(r.record_type==='ETF'?'ETF':'US equity')+' · Qty: '+esc(r.quantity??'—')+'</small><small>Invested '+inrValue(cv.invested_value_inr)+' · Current '+inrValue(cv.current_value_inr)+'</small></span><b>'+new Intl.NumberFormat('en-US',{style:'currency',currency:String(r.currency||'USD'),maximumFractionDigits:2}).format(Number(r.current_value||0))+' USD</b></div>'}).join('')+'</div></details>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.mutual_fund||'◫')+'</span><div><b>Mutual funds</b><small>Angel One fund portfolio</small></div><strong>'+money(w.mutualFunds)+'</strong></div><div class="investment-category-metrics"><div><small>Invested</small><b>'+money(mfInvested)+'</b></div><div><small>Gain / return</small><b class="positive">'+money(w.mutualFunds-mfInvested)+'</b></div></div>'+(mfRows.length?'<details class="investment-holdings-toggle"><summary>Show '+mfRows.length+' mutual fund holdings</summary><div class="investment-holdings">'+mfRows.map(r=>{const q=dematQty[r.name.toLowerCase().trim()];return '<div><span>'+esc(r.name)+(q?'<small>Last recorded units (31 Oct): '+esc(q)+'</small>':'<small>Units not captured in latest snapshot</small>')+'</span><b>'+money(r.value)+'</b></div>'}).join('')+'</div></details>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.gold||'◆')+'</span><div><b>Gold</b><small>Paytm Gold</small></div><strong>'+money(w.gold)+'</strong></div>'+(actualGold?'<p class="investment-note">Actual digital gold · '+esc(actualGold.quantity)+' ('+esc(actualGold.date)+')</p>':'<p class="investment-note">Actual gold quantity not available in saved source.</p>')+(goldCoinQuantity?'<p class="investment-note">Paytm reward coins · '+esc(goldCoinQuantity)+' (not included in gold asset value)</p>':'')+'</section><section class="investment-category"><div class="investment-category-head"><span class="investment-category-icon">'+esc(window.wealthCategorySymbols?.silver||'◇')+'</span><div><b>Silver</b><small>Paytm Silver</small></div><strong>'+money(w.silver)+'</strong></div>'+(silverQuantity?'<p class="investment-note">Actual digital silver · '+esc(silverQuantity.quantity)+' ('+esc(silverQuantity.date)+')</p>':'<p class="investment-note">Actual silver quantity not available in saved source.</p>')+'</section></div>'}
function wealthExpandedHtml(key,w){let rows=[];if(key==='casa'){Object.entries(w.latestAccounts||{}).forEach(([name,value])=>rows.push({label:name,amount:value}));if(w.roarbank>0)rows.push({label:'Roarbank savings account',amount:w.roarbank});}if(key==='liabilities')items.filter(x=>x.kind==='liability').forEach(x=>rows.push({label:(x.account||x.category||'Credit usage')+' · '+(x.description||''),amount:Number(x.amount||0),date:String(x.occurred_on||'').slice(0,10)}));const total=key==='casa'?w.casa:key==='investments'?w.investments:w.liabilities;const body=key==='investments'?investmentBreakdownHtml(w):(rows.length?'<div class="wealth-detail-list">'+rows.map(r=>'<div class="wealth-detail-row"><span>'+esc(r.label)+(r.date?'<small>'+esc(r.date)+'</small>':'')+'</span><b>'+money(r.amount||0)+'</b></div>').join('')+'</div>':'<p class="muted">No detailed records available in the latest saved data.</p>');return '<div class="wealth-expanded" id="wealth-expanded-'+key+'"><div class="wealth-expanded-head"><b>'+({casa:'Cash & deposits breakdown',investments:'Investment breakdown',liabilities:'Outstanding credit usage'}[key])+'</b><strong>'+money(total)+'</strong></div>'+body+'</div>'}
function renderTopWealth(){const el=$('stats');if(!el)return;const w=wealthPosition();const cards=[['casa','⌂','CASA',w.casa,'Bank · Atom · Roarbank','casa-icon'],['investments','↗','INVESTMENTS',w.investments,'Equity · MF · Metals · FD · PF','invest-icon'],['liabilities','−','LIABILITIES',w.liabilities,'Credit used','liability-icon']];el.innerHTML='<div class="wealth-hero"><div><div class="eyebrow">TOTAL BALANCE AVAILABLE</div><div class="wealth-total">'+money(w.total)+'</div><div class="wealth-equation">CASA + Investments − Liabilities</div></div><div class="wealth-hero-mark">₹</div></div><div class="wealth-kpis">'+cards.map(c=>'<button type="button" class="wealth-kpi '+(c[0]==='liabilities'?'liability-kpi':'')+'" data-wealth-expand="'+c[0]+'" aria-expanded="'+(wealthExpanded===c[0]?'true':'false')+'" aria-controls="wealth-expanded-'+c[0]+'"><span class="kpi-top"><i class="kpi-icon '+c[5]+'">'+c[1]+'</i><small>'+c[2]+'</small><i class="wealth-chevron">'+(wealthExpanded===c[0]?'−':'+')+'</i></span><strong>'+money(c[3])+'</strong><span>'+c[4]+' · Tap for details</span></button>').join('')+'</div>'+(wealthExpanded?wealthExpandedHtml(wealthExpanded,w):'');el.querySelectorAll('[data-wealth-expand]').forEach(b=>b.addEventListener('click',()=>{wealthExpanded=wealthExpanded===b.dataset.wealthExpand?null:b.dataset.wealthExpand;renderTopWealth()}))}

function categorySpendHtml(){const expenses=items.filter(x=>x.kind==='expense');const totals={};expenses.forEach(x=>{const k=String(x.category||'Uncategorised').trim()||'Uncategorised';totals[k]=(totals[k]||0)+Number(x.amount||0)});const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]);const total=rows.reduce((n,r)=>n+r[1],0);const months=monthlySpendStats().months||1;const overallAverage=total/months;return '<section class="chart-card category-spend" id="categorySpend"><div class="chart-head"><div><h4>Category spend vs monthly average</h4><p>Each category shows total spent and its monthly average across '+months+' recorded calendar month(s)</p></div><button type="button" class="ghost spend-close" data-spend-close>Close</button></div>'+(rows.length?'<div class="category-spend-benchmark"><span>Overall average monthly spend</span><b>'+money(overallAverage)+'</b></div><div class="category-spend-list">'+rows.map(([name,value])=>{const avg=value/months;const share=total?value/total*100:0;const relative=overallAverage?avg/overallAverage*100:0;return '<div class="category-spend-row"><div class="category-spend-label"><b>'+esc(name)+'</b><strong>'+money(value)+'</strong></div><div class="category-spend-compare"><span>Monthly avg <b>'+money(avg)+'</b></span><span>'+relative.toFixed(1)+'% of overall avg</span></div><div class="category-spend-track"><i style="width:'+Math.max(0,Math.min(100,relative))+'%"></i></div><small>'+share.toFixed(1)+'% of total expenses · '+money(avg)+' per month</small></div>'}).join('')+'</div><div class="category-spend-total"><span>Total expenses · monthly average</span><b>'+money(total)+' · '+money(overallAverage)+'/mo</b></div>':'<p class="muted">No expense categories have been recorded yet.</p>')+'</section>'}
function monthCategorySpendHtml(){const now=new Date(),key=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'),expenses=items.filter(x=>x.kind==='expense'&&monthKey(x.occurred_on)===key),totals={};expenses.forEach(x=>{const k=String(x.category||'Uncategorised').trim()||'Uncategorised';totals[k]=(totals[k]||0)+Number(x.amount||0)});const rows=Object.entries(totals).sort((a,b)=>b[1]-a[1]),total=rows.reduce((n,r)=>n+r[1],0),days=now.getDate(),allMonths=monthlySpendStats().months||1;return '<section class="chart-card category-spend" id="monthCategorySpend"><div class="chart-head"><div><h4>This month: category spending</h4><p>'+esc(now.toLocaleString('en-IN',{month:'long',year:'numeric'}))+' · actual spend versus averages</p></div><button type="button" class="ghost spend-close" data-spend-close>Close</button></div>'+(rows.length?'<div class="category-spend-benchmark"><span>This month total · daily average</span><b>'+money(total)+' · '+money(total/Math.max(1,days))+'/day</b></div><div class="category-spend-list">'+rows.map(([name,value])=>{const daily=value/Math.max(1,days),share=total?value/total*100:0;return '<div class="category-spend-row"><div class="category-spend-label"><b>'+esc(name)+'</b><strong>'+money(value)+'</strong></div><div class="category-spend-compare"><span>Daily avg <b>'+money(daily)+'</b></span><span>Month-end run-rate '+money(daily*new Date(now.getFullYear(),now.getMonth()+1,0).getDate())+'</span></div><div class="category-spend-track"><i style="width:'+Math.max(0,Math.min(100,share))+'%"></i></div><small>'+share.toFixed(1)+'% of this month · historical monthly average '+money(value/allMonths)+'</small></div>'}).join('')+'</div><div class="category-spend-total"><span>This month · daily average</span><b>'+money(total)+' · '+money(total/Math.max(1,days))+'/day</b></div>':'<p class="muted">No expense categories have been recorded this month.</p>')+'</section>'}
function analyticsHtml(){const stats=monthlySpendStats(),daily=dailySpendStats(),cash=monthlyCashSeries(),yearly=yearlyAverageSpendSeries(),balances=historicalCashBalances();return '<div class="analytics-grid"><article class="mini-card spend-click-card" data-month-spend-breakdown role="button" tabindex="0" aria-expanded="'+(showMonthSpend?'true':'false')+'"><small>DAILY AVERAGE · THIS MONTH</small><strong>'+money(daily.monthAverage)+'</strong><span>'+esc(daily.monthLabel)+' · '+money(daily.monthTotal)+' spent over '+daily.monthDays+' elapsed days</span></article><article class="mini-card"><small>DAILY AVERAGE · THIS YEAR</small><strong>'+money(daily.yearAverage)+'</strong><span>'+daily.yearLabel+' year-to-date · '+money(daily.yearTotal)+' spent over '+daily.yearDays+' elapsed days</span></article><article class="mini-card spend-click-card" data-spend-breakdown role="button" tabindex="0" aria-expanded="'+(showCategorySpend?'true':'false')+'"><small>AVERAGE MONTHLY SPEND</small><strong>'+money(stats.average)+'</strong><span>Based on '+stats.months+' calendar month(s) · expenses only · Tap for category breakdown</span></article><article class="mini-card"><small>HISTORICAL EXPENSES</small><strong>'+money(stats.total||0)+'</strong><span>Transfer and investment movements excluded</span></article></div>'+(showMonthSpend?monthCategorySpendHtml():'')+(showCategorySpend?categorySpendHtml():'')+'<section class="chart-card"><div class="chart-head"><div><h4>Cash flow trend</h4><p>Monthly income versus spending · latest 12 months</p></div></div>'+svgLineChart(cash,['income','spend'],['Money in','Spending'],v=>money(v))+'</section><section class="chart-card"><div class="chart-head"><div><h4>Average monthly spend by year</h4><p>Year-wise average · expenses only · months with recorded expenses</p></div></div>'+svgLineChart(yearly,['average'],['Average monthly spend'],v=>money(v))+(yearly.length?'<p class="chart-foot">'+yearly.map(x=>esc(x.month)+': '+money(x.average)+' / month · '+money(x.total)+' total').join(' &nbsp; | &nbsp; ')+'</p>':'')+'</section><section class="chart-card"><div class="chart-head"><div><h4>Bank balance history</h4><p>Historical cash balances from saved account snapshots</p></div></div>'+svgLineChart(balances.map(d=>({month:d.date.slice(5),total:d.total})),['total'],['Total bank cash'],v=>money(v))+(balances.length?'<p class="chart-foot">Latest recorded balance: '+money(balances[balances.length-1].total)+' · '+balances[balances.length-1].date+'</p>':'')+'</section>'}
async function loadSnapshot(){try{const d=await api('/api/snapshot');sourceSections=[];(d.snapshots||[]).forEach(snap=>{let p=snap.payload;if(typeof p==='string'){try{p=JSON.parse(p)}catch{p={}}}(p.sections||[]).forEach(s=>sourceSections.push({...s,_source:snap.source_name,_date:String(snap.snapshot_date||'').slice(0,10)}))});$('snapshotStatus').textContent=sourceSections.length+' source sections · '+(d.snapshots||[]).length+' saved snapshots';$('sourceCount').textContent=sourceSections.length+' imported sections';renderTopWealth();renderView(activeView)}catch(e){$('snapshotStatus').textContent='Could not load source data';$('sourceCount').textContent=e.message}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function isInvestmentRecord(s){const text=(String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ')+' '+(s.notes||[]).join(' ')).toLowerCase();return /fixed deposit|epf\s*\/\s*eps|employee epf|eps pension|investment|portfolio|mutual fund|stocks|equity|demat|angel one|zerodha/.test(text)}
function isBankBalanceSection(s){const h=String(s.heading||'').toLowerCase();const headers=(s.tables||[]).flatMap(t=>t[0]||[]).map(v=>String(v).toLowerCase());return /bank & cash accounts|latest bank balances|latest balance snapshot|bank balance snapshot|account balances|roarbank credit line and savings/.test(h)||((headers.includes('account')||headers.includes('account / bucket shown'))&&headers.some(v=>v.includes('latest balance')||v==='displayed amount'))}
function bankName(s){const x=String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ');const banks=[['Bank of India',/\bboi\b|bank of india/i],['HDFC Bank',/hdfc/i],['State Bank of India',/\bsbi\b|state bank of india/i],['Slice',/slice/i],['Roarbank',/roarbank|roar bank/i],['Other bank',/bank|account/i]];return (banks.find(b=>b[1].test(x))||banks[banks.length-1])[0]}
function groupFor(s){return isBankBalanceSection(s)?'banks':'other'}
const views=[['overview','Overview'],['banks','Bank Balances'],['investments','Investments'],['stock-advisor','Stock Advisor'],['angel-one','Angel One'],['other','Other Records'],['transactions','Transactions'],['alerts','Alerts'],['subscriptions','Active Subscriptions & Mandates'],['more','More']];
function cleanHeading(s){return String(s.heading||'').replace(/^\d{1,2}\s+November\s+2026\s*[—–-]\s*/i,'').replace(/^Latest balance snapshot\s*[—–-]\s*/i,'').replace(/^\d+\\.\s*/,'');}
function sectionContent(s){const tables=(s.tables||[]).map(rows=>'<div class="snapshot-table-wrap"><table class="snapshot-table"><tbody>'+rows.map((r,ri)=>'<tr>'+r.map(cell=>ri===0?'<th>'+esc(cell)+'</th>':'<td>'+esc(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('');const notes=(s.notes||[]).map(n=>'<li>'+esc(n)+'</li>').join('');return '<div class="source-meta">Source: '+esc(s._source||'HTML source')+'</div>'+tables+(notes?'<ul class="snapshot-notes">'+notes+'</ul>':'')}
function sectionHtml(s,i){return '<details class="snapshot-section" '+(i<2?'open':'')+'><summary>'+esc(cleanHeading(s))+'</summary>'+sectionContent(s)+'</details>'}
function mergedOtherHtml(sections){return '<div class="merged-records">'+sections.map((s,i)=>'<section class="merged-record"><h4>'+esc(s.heading)+'</h4>'+sectionContent(s)+'</section>').join('')+'</div>'}
function accountKey(label){const x=String(label||'').toLowerCase().replace(/[•·]/g,' ').replace(/\s+/g,' ').trim();const sections=accountingTemplate?.sections||[];const reward=sections.find(s=>s.key==='rewards');if((reward?.assets||[]).some(a=>x.includes(String(a).toLowerCase())))return null;const aliases=accountingTemplate?.accountAliases||{};for(const [canonical,names] of Object.entries(aliases)){if([canonical,...names].some(a=>x.includes(String(a).toLowerCase())))return canonical}if(/\bmonies\b|reward coins|reward points|cashback coins/.test(x))return null;return String(label||'Other account').trim();}
function accountRecords(key){return sourceSections.filter(s=>{const text=(String(s.heading||'')+' '+(s.tables||[]).flat().flat().join(' ')+' '+(s.notes||[]).join(' ')).toLowerCase();const k=key.toLowerCase();return k==='slice'?text.includes('slice'):k==='bank of india'?text.includes('bank of india')||text.includes('boi'):k==='hdfc bank'?text.includes('hdfc'):k==='roarbank'?text.includes('roarbank')||text.includes('roar bank'):k==='atom'?text.includes('atom'):k==='fixed deposits'?text.includes('fixed deposit'):text.includes(k)});}
function openBank(key){activeBank=key;renderView('bank-detail');}
function bankCards(sections){const seen=new Set();const cards=[];sections.forEach(s=>{let rendered=false;(s.tables||[]).forEach(rows=>{if(!rows.length)return;const headers=rows[0].map(v=>String(v).toLowerCase());const ai=headers.findIndex(v=>v==='account'||v==='account / bucket shown');const bi=headers.findIndex(v=>v.includes('latest balance')||v==='displayed amount');if(ai<0||bi<0){if(/roarbank credit line and savings/i.test(String(s.heading||''))){const savings=rows.slice(1).find(r=>/^savings account$/i.test(String(r[0]||'')));if(savings&&savings[1]&&!seen.has('Roarbank')){seen.add('Roarbank');cards.push('<button type="button" class="bank-balance-card" data-bank="Roarbank"><div class="bank-card-head"><h4>Roarbank</h4><span>Savings account</span></div><div class="bank-metrics"><div class="bank-metric"><small>Latest balance</small><strong>'+esc(savings[1])+'</strong></div></div><span class="bank-open">View account details →</span><div class="source-meta">Updated '+esc(s._date||'')+'</div></button>')}}return}rows.slice(1).forEach(row=>{if(!row[ai])return;const label=String(row[ai]);if(/\\b(?:fixed\\s*deposits?|fds?|term\\s*deposits?)\\b/i.test(label))return;const bank=accountKey(label);if(/total|visible accounts total/i.test(label)||seen.has(bank))return;seen.add(bank);const rest=row.map((v,k)=>'<div class="bank-metric"><small>'+esc(rows[0][k])+'</small><strong>'+esc(v)+'</strong></div>').join('');cards.push('<button type="button" class="bank-balance-card" data-bank="'+esc(bank)+'"><div class="bank-card-head"><h4>'+esc(bank)+'</h4><span>'+esc(label)+'</span></div><div class="bank-metrics">'+rest+'</div><span class="bank-open">View account details →</span><div class="source-meta">Updated '+esc(s._date||'')+'</div></button>')});rendered=true});if(!rendered)cards.push('<section class="merged-record"><h4>'+esc(s.heading)+'</h4>'+sectionContent(s)+'</section>')});const order=['Slice','HDFC Bank','Bank of India','Roarbank','Atom','Fixed deposits'];cards.sort((a,b)=>{const get=x=>{const m=x.match(/data-bank=\"([^\"]+)/);return m?m[1]:''};const ai=order.indexOf(get(a)),bi=order.indexOf(get(b));return (ai<0?99:ai)-(bi<0?99:bi)});return cards.join('')}
function angelOneHtml(){return '<section class="chart-card"><div class="chart-head"><div><h4>Angel One · SmartAPI</h4><p>Secure, read-only sync of holdings, funds and positions</p></div><span class="pill">READ ONLY</span></div><p class="muted">Broker credentials stay on the server in Vercel environment variables. They are never stored in browser code or displayed here.</p><button type="button" class="primary" data-angel-refresh>Connect / Refresh Angel One</button><div id="angelResult" class="muted" style="margin-top:14px">Tap Connect to check the SmartAPI connection.</div></section>'}
async function loadAngelOne(){const box=$('angelResult');if(!box)return;box.textContent='Connecting securely to Angel One…';try{const d=await api('/api/angel');if(!d.connected){box.innerHTML=d.setupRequired?'<b>Setup required</b><p>Configure these Vercel environment variables: '+(d.missing||[]).map(esc).join(', ')+'</p><p class="muted">Then redeploy and try again. Do not share your PIN, TOTP seed or API key in chat.</p>':'<p class="error">'+esc(d.error||'Connection unavailable')+'</p>';return}const rows=Array.isArray(d.holdings)?d.holdings:[];const fmt=v=>v==null?'—':esc(String(v));const keys=rows.length?Object.keys(rows[0]):[];box.innerHTML='<div class="analytics-grid"><article class="mini-card"><small>HOLDINGS</small><strong>'+rows.length+'</strong></article><article class="mini-card"><small>POSITIONS</small><strong>'+(Array.isArray(d.positions)?d.positions.length:0)+'</strong></article><article class="mini-card"><small>SYNCED</small><strong>'+esc(new Date(d.fetchedAt).toLocaleTimeString())+'</strong></article></div>'+(rows.length?'<div class="table-wrap"><table><thead><tr>'+keys.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td>'+fmt(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p class="muted">No holdings returned by Angel One.</p>')+'<details><summary>Funds / RMS and positions (raw response)</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(JSON.stringify({rms:d.rms,positions:d.positions},null,2))+'</pre></details>'}catch(e){box.innerHTML='<p class="error">'+esc(e.message)+'</p>'}}
function stockAdvisorHtml(){return '<section class="stock-advisor-intro"><div class="eyebrow">INDIAN EQUITY RESEARCH</div><h3>Stock Advisor</h3><p>Research-backed BUY, HOLD and SELL watchlists. Reports are saved in your Wealth database after the scheduled review completes.</p><div class="stock-advisor-tags"><span>Indian equities only</span><span>BUY / HOLD / SELL</span><span>Portfolio risk</span><span>MTF review</span></div><button type="button" class="ghost" data-stock-advisor-refresh>Reload saved report</button><span id="stockAdvisorUpdated" class="muted"></span></section><div id="stockAdvisorContent"><p class="muted">Loading your latest saved Stock Advisor report…</p></div>'}
async function loadStockAdvisor(){
 const box=document.getElementById('stockAdvisorContent'),stamp=document.getElementById('stockAdvisorUpdated');
 if(!box)return;
 box.innerHTML='<p class="muted">Loading the latest saved report…</p>';
 try{
  const d=await api('/api/stock-advisor');
  const report=d.report||null;
  const holdings=Array.isArray(d.holdings)?d.holdings:[];
  const recommendations=Array.isArray(report?.report_json?.recommendations)?report.report_json.recommendations:[];
  const decisions=report?.report_json?.portfolio_review||{};
  const summary=report?.report_json?.summary||report?.report_text||'';
  const counts=recommendations.reduce((a,r)=>{const action=String(r.action||'REVIEW').toUpperCase();a[action]=(a[action]||0)+1;return a},{});
  const signal=(action)=>'<span class="advisor-signal advisor-'+action.toLowerCase()+'">'+action+'</span>';
  const reportDate=report?.run_at?new Date(report.run_at).toLocaleString('en-IN'):'Date unavailable';
  const recommendationCards=recommendations.length?recommendations.map((r,i)=>{
   const action=String(r.action||'REVIEW').toUpperCase();
   const symbol=r.symbol||r.ticker||r.name||'—';
   const company=r.company||r.name||'';
   const reason=r.reason||r.rationale||'No reasoning was saved for this call.';
   const condition=r.entry_condition||r.price_condition||'No entry / exit condition saved.';
   return '<article class="advisor-stock-card"><div class="advisor-stock-top"><div class="advisor-stock-name"><b>'+esc(symbol)+'</b><small>'+esc(company)+'</small></div>'+signal(action)+'</div><p>'+esc(reason)+'</p><details class="advisor-more"><summary>Entry / exit conditions</summary><p>'+esc(condition)+'</p></details></article>';
  }).join(''):'<p class="muted">No structured BUY / HOLD / SELL calls were saved in the latest run.</p>';
  const holdingCards=holdings.length?holdings.map(h=>'<article class="advisor-holding-card"><div class="advisor-stock-name"><b>'+esc(h.name||h.ticker||'Holding')+'</b><small>'+esc(h.ticker||'Indian equity')+'</small></div><div class="advisor-holding-metrics"><div><small>Quantity</small><b>'+esc(h.quantity==null?'—':h.quantity)+'</b></div><div><small>Saved value</small><b>'+money(h.current_value||0)+'</b></div></div><small class="advisor-asof">Updated '+esc(h.balance_as_of?new Date(h.balance_as_of).toLocaleString('en-IN'):'date unavailable')+'</small></article>').join(''):'<p class="muted">No Indian equity holdings are currently saved in Wealth positions.</p>';
  const summaryBlock=summary?'<section class="advisor-panel advisor-report"><div class="advisor-section-head"><div><small class="eyebrow">LATEST REVIEW</small><h4>Advisor summary</h4></div><span class="pill">SAVED</span></div><p class="advisor-summary-text">'+esc(summary)+'</p><details class="advisor-more"><summary>Read full report</summary><p class="advisor-full-report">'+esc(report?.report_text||summary)+'</p></details><small class="advisor-asof">Saved '+esc(reportDate)+'</small></section>':'<section class="advisor-panel"><h4>No saved advisor report yet</h4><p class="muted">The latest completed review will appear here after it is saved to Wealth.</p></section>';
  const health=(decisions.diversification||decisions.mtf)?'<section class="advisor-panel"><div class="advisor-section-head"><h4>Portfolio risk</h4><span class="pill">REVIEW</span></div>'+(decisions.diversification?'<div class="advisor-risk-item"><b>Diversification</b><p>'+esc(decisions.diversification)+'</p></div>':'')+(decisions.mtf?'<div class="advisor-risk-item"><b>MTF exposure</b><p>'+esc(decisions.mtf)+'</p></div>':'')+'</section>':'';
  box.innerHTML=(report?'<section class="advisor-kpis"><article class="advisor-kpi"><small>BUY</small><b>'+Number(counts.BUY||0)+'</b></article><article class="advisor-kpi"><small>HOLD</small><b>'+Number(counts.HOLD||0)+'</b></article><article class="advisor-kpi"><small>SELL</small><b>'+Number(counts.SELL||0)+'</b></article></section>':'')+summaryBlock+health+'<section class="advisor-panel"><div class="advisor-section-head"><div><small class="eyebrow">RESEARCH DECISIONS</small><h4>Recommendations <span class="advisor-count">'+recommendations.length+'</span></h4></div></div><div class="advisor-stock-list">'+recommendationCards+'</div></section><section class="advisor-panel"><div class="advisor-section-head"><div><small class="eyebrow">SAVED POSITIONS</small><h4>Indian equity holdings <span class="advisor-count">'+holdings.length+'</span></h4></div></div><div class="advisor-holding-list">'+holdingCards+'</div></section>';
  if(stamp)stamp.textContent=report?' · Updated '+reportDate:' · Waiting for first saved report';
 }catch(e){box.innerHTML='<section class="advisor-panel"><h4>Stock Advisor unavailable</h4><p class="error">'+esc(e.message||'Unable to load advisor data.')+'</p></section>'}
}
function moreHubHtml(){const banks=sourceSections.filter(isBankBalanceSection).length;const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s)).length;const due=plannedBills.filter(b=>b.status==='planned').length;const rows=[{group:'YOUR MONEY',items:[['banks','Bank accounts','Balances, account snapshots and details','▣',banks],['investments','Investments','Stocks, mutual funds and metals','↗',null],['other','Other records','Imported statements and saved records','◫',other]]},{group:'ACTIVITY & REMINDERS',items:[['transactions','Transactions','Income, spending and transfers','≡',items.length],['alerts','Alerts & bills','Upcoming payments and reminders','!',due],['subscriptions','Subscriptions & mandates','Recurring payments and authorisations','⟳',subscriptions.length]]},{group:'TOOLS',items:[['stock-advisor','Stock Advisor','Research and portfolio signals for Indian stocks','⌁',null],['overview','Financial overview','Charts, cash flow and account summary','⌂',null]]}];return '<section class="more-hub"><div class="more-welcome"><div class="eyebrow">QUICK ACCESS</div><h3>Everything in one place</h3><p>Choose what you want to review. Your saved financial records stay unchanged.</p></div>'+rows.map(g=>'<section class="more-group"><h4>'+g.group+'</h4><div class="more-list">'+g.items.map(x=>'<button type="button" class="more-link" data-view="'+x[0]+'"><span class="more-link-icon">'+x[3]+'</span><span class="more-link-copy"><b>'+x[1]+'</b><small>'+x[2]+'</small></span>'+(x[4]===null?'':'<span class="more-link-count">'+x[4]+'</span>')+'<span class="more-link-arrow">›</span></button>').join('')+'</div></section>').join('')+'<section class="more-group"><h4>ACCOUNT</h4><div class="more-list"><a class="more-link" href="/api/clear-session"><span class="more-link-icon">↻</span><span class="more-link-copy"><b>Clear session</b><small>Clear this browser login session</small></span><span class="more-link-arrow">›</span></a><button type="button" class="more-link" data-action="logout"><span class="more-link-icon">⇥</span><span class="more-link-copy"><b>Sign out</b><small>End your current account session</small></span><span class="more-link-arrow">›</span></button></div></section><div class="more-footnote"><span>●</span> '+sourceSections.length+' imported sections · '+items.length+' ledger entries · data preserved</div></section>'}
function activityRowsHtml(){
 const q=String($('activitySearch')?.value||'').trim().toLowerCase(),kind=$('activityKind')?.value||'all',account=$('activityAccount')?.value||'all',from=$('activityFrom')?.value||'',to=$('activityTo')?.value||'';
 const rows=items.filter(x=>{const date=String(x.occurred_on||'').slice(0,10),hay=[x.category,x.description,x.account,x.kind,x.amount].join(' ').toLowerCase();return (kind==='all'||x.kind===kind)&&(account==='all'||String(x.account||'')===account)&&(!from||date>=from)&&(!to||date<=to)&&(!q||hay.includes(q))}).sort((a,b)=>String(b.occurred_on).localeCompare(String(a.occurred_on)));
 const count=$('activityCount');if(count)count.textContent=rows.length+' of '+items.length+' transactions';const filterCount=(kind!=='all'?1:0)+(account!=='all'?1:0)+((from||to)?1:0);const filterBadge=$('activityFilterBadge');if(filterBadge){filterBadge.textContent=filterCount;filterBadge.hidden=!filterCount}document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b.dataset.activityKind===kind));
 const active=[];if(kind!=='all')active.push({id:'activityKind',label:({income:'Money in',expense:'Money out',transfer:'Transfers',investment:'Investments',liability:'Liabilities'})[kind]||kind});if(account!=='all')active.push({id:'activityAccount',label:account});if(from||to)active.push({id:'activityDate',label:(from||'Any date')+' – '+(to||'Today')});
 const chips=$('activityActiveFilters');if(chips)chips.innerHTML=active.map(x=>'<button type="button" class="activity-filter-chip" data-clear-filter="'+x.id+'">'+esc(x.label)+' <span>×</span></button>').join('');
 const groups=[];rows.forEach(x=>{const date=String(x.occurred_on||'').slice(0,10)||'Undated';let g=groups[groups.length-1];if(!g||g.date!==date){g={date,rows:[]};groups.push(g)}g.rows.push(x)});
 const target=$('activityRows');if(!target)return;
 target.innerHTML=rows.length?groups.map(g=>'<section class="activity-day"><div class="activity-day-heading">'+esc(g.date)+'</div>'+g.rows.map(x=>{const sign=x.kind==='income'?'+':x.kind==='expense'||x.kind==='liability'?'-':'';const label=x.kind==='income'?'Money in':x.kind==='expense'?'Money out':x.kind==='transfer'?'Transfer':x.kind==='investment'?'Investment':x.kind==='liability'?'Liability':x.kind;const icon=x.kind==='income'?'arrow-down-left':x.kind==='expense'?'arrow-up-right':x.kind==='transfer'?'arrow-left-right':x.kind==='investment'?'chart-no-axes-combined':'receipt';return '<article class="activity-item"><span class="activity-item-icon">'+(x.kind==='income'?'↙':x.kind==='expense'?'↗':x.kind==='transfer'?'⇄':x.kind==='investment'?'⌁':'₹')+'</span><div class="activity-item-copy"><b>'+esc(x.description||x.category||label)+'</b><small>'+esc(x.category||label)+' · '+esc(x.account||'No account')+'</small></div><div class="activity-item-amount"><strong class="'+(x.kind==='income'?'income':x.kind==='expense'?'expense':'')+'">'+sign+money(x.amount)+'</strong><small>'+esc(label)+'</small></div><button class="delete" data-id="'+esc(x.id)+'" aria-label="Delete transaction">×</button></article>'}).join('')+'</section>').join(''):'<div class="activity-empty"><span>⌕</span><b>No transactions found</b><p>Try another search or clear your filters.</p><button type="button" class="ghost" id="activityReset">Clear filters</button></div>';
 const clear=$('activityClearAll');if(clear)clear.hidden=active.length===0;
}
function activitiesHtml(){
 const kinds=[['all','All types'],['income','Money in'],['expense','Money out'],['transfer','Transfers'],['investment','Investments'],['liability','Liabilities']];
 const accountsList=[...new Set(items.map(x=>String(x.account||'')).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 return '<section class="card history activity-card"><div class="historyhead"><div><div class="eyebrow">YOUR MONEY, IN ONE PLACE</div><h3>Transactions</h3><p class="activity-subtitle">Search, filter and review your money activity.</p></div><span id="activityCount" class="pill">'+items.length+' transactions</span></div><div class="activity-search-row"><label class="activity-search"><span>⌕</span><input id="activitySearch" type="search" placeholder="Search merchant, note or account…" autocomplete="off"></label><button type="button" class="activity-filter-toggle" id="activityFilterToggle" aria-expanded="false" aria-controls="activityAdvancedFilters">☷ <span>Filters</span><i id="activityFilterBadge" hidden>0</i></button></div><div class="activity-quick-filters" role="group" aria-label="Transaction type"><button type="button" class="active" data-activity-kind="all">All</button><button type="button" data-activity-kind="income">Money in</button><button type="button" data-activity-kind="expense">Money out</button><button type="button" data-activity-kind="transfer">Transfers</button></div><details class="activity-advanced" id="activityAdvancedFilters"><summary>More filters</summary><div class="activity-filter-fields"><label>Transaction type<select id="activityKind">'+kinds.map(k=>'<option value="'+k[0]+'">'+k[1]+'</option>').join('')+'</select></label><label>Account<select id="activityAccount"><option value="all">All accounts</option>'+accountsList.map(a=>'<option value="'+esc(a)+'">'+esc(a)+'</option>').join('')+'</select></label><div class="activity-date-presets"><span>Date range</span><div><button type="button" data-activity-date="today">Today</button><button type="button" data-activity-date="7">7 days</button><button type="button" data-activity-date="30">30 days</button><button type="button" data-activity-date="all" class="active">Any time</button></div></div><div class="activity-date-inputs"><label>From<input id="activityFrom" type="date"></label><label>To<input id="activityTo" type="date"></label></div><div class="activity-filter-actions"><button type="button" class="ghost" id="activityReset">Reset</button><button type="button" class="primary" id="activityApply">Apply filters</button></div></div></details><div id="activityActiveFilters" class="activity-active-filters"></div><button type="button" id="activityClearAll" class="activity-clear-all" hidden>Clear all filters</button><div id="activityRows" class="activity-list"></div></section>';
}
function renderView(view){activeView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('sourceNav').classList.remove('more-open');const target=$('viewContent');if(!target)return;const banks=sourceSections.filter(isBankBalanceSection);const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s));$('viewTitle').textContent=(views.find(v=>v[0]===view)||views[0])[1];const viewEyebrow=$('viewTitle').previousElementSibling;if(viewEyebrow)viewEyebrow.textContent=view==='more'?'QUICK ACCESS':'SOURCE DATA · PRESERVED';if(view==='more'){target.innerHTML=moreHubHtml()}else if(view==='alerts'){target.innerHTML=plannedBillsHtml()}else if(view==='subscriptions'){target.innerHTML=subscriptionsHtml()}else if(view==='stock-advisor'){target.innerHTML=stockAdvisorHtml();loadStockAdvisor()}else if(view==='angel-one'){target.innerHTML=angelOneHtml()}else if(view==='bank-detail'){const records=accountRecords(activeBank);target.innerHTML='<button type="button" class="ghost" id="backToBanks">← Back to accounts</button><h3 class="group-title">'+esc(activeBank)+' · Account details</h3>'+(records.length?records.map(s=>'<section class="merged-record"><h4>'+esc(cleanHeading(s))+'</h4>'+sectionContent(s)+'<div class="source-meta">Source: '+esc(s._source||'Saved snapshot')+' · Updated '+esc(s._date||'')+'</div></section>').join(''):'<p class="muted">No saved details found for this account yet.</p>')}else if(view==='overview'){target.innerHTML=alertsBannerHtml()+analyticsHtml()+'<div class="overview-grid"><article class="mini-card"><small>CASH BALANCE</small><strong>'+money((historicalCashBalances().slice(-1)[0]||{}).total||0)+'</strong><span>Latest saved bank balance snapshot</span></article><article class="mini-card"><small>LIABILITIES</small><strong>'+money(items.filter(x=>x.kind==='liability').reduce((n,x)=>n+Number(x.amount||0),0))+'</strong><span>Recorded liability entries</span></article><article class="mini-card"><small>BANK ACCOUNTS</small><strong>'+banks.length+'</strong></article><article class="mini-card"><small>OTHER RECORDS</small><strong>'+other.length+'</strong></article><article class="mini-card"><small>LIVE TRANSACTIONS</small><strong>'+items.length+'</strong></article></div><p class="muted">Open Banks to view account balances and details.</p>'}else if(view==='banks'){target.innerHTML=banks.length?bankCards(banks):'<p class="muted">No bank balance records found.</p>'}else if(view==='other'){target.innerHTML=other.length?mergedOtherHtml(other):'<p class="muted">No other financial records found.</p>'}else if(view==='investments'){const invested=items.filter(x=>x.kind==='investment').sort((a,b)=>String(b.occurred_on).localeCompare(String(a.occurred_on)));const fdRows=positions.filter(p=>p.category==='INVESTMENT'&&p.record_type==='FIXED_DEPOSIT'&&p.metadata?.reconciliation_status!=='pending_reconciliation');const fdTotal=fdRows.reduce((n,p)=>n+Number(p.current_value||0),0);const total=invested.reduce((n,x)=>n+Number(x.amount||0),0)+fdTotal;const records=sourceSections.filter(isInvestmentRecord);target.innerHTML='<div class="analytics-grid"><article class="mini-card"><small>RECORDED INVESTMENTS</small><strong>'+invested.length+'</strong><span>Investment entries in your ledger</span></article><article class="mini-card"><small>TOTAL INVESTED</small><strong>'+money(total)+'</strong><span>Sum of recorded investment entries only</span></article></div><h3 class="group-title">Investment activity</h3>'+(invested.length?'<div class="entries">'+invested.map(x=>'<div class="entry"><div><b>'+esc(x.category)+'</b><small>'+esc(x.description||'Investment')+' · '+esc(x.account||'No account')+' · '+esc(String(x.occurred_on).slice(0,10))+'</small></div><span class="value">'+money(x.amount)+'</span></div>').join('')+'</div>':'<p class="muted">No investment transactions have been recorded yet. Existing records are preserved.</p>')+'<h3 class="group-title">Imported investment records</h3>'+(records.length?mergedOtherHtml(records):'<p class="muted">No imported investment or portfolio snapshots found.</p>');}else if(view==='bank-detail'){const key=activeBank||'Bank';$('viewTitle').textContent=key;target.innerHTML='<button type="button" class="back-button" id="backToBanks">← All accounts</button><h3 class="group-title">'+esc(key)+' account details</h3>'+accountRecords(key).map(sectionHtml).join('')}else if(view==='transactions'){target.innerHTML=activitiesHtml();activityRowsHtml()}const bindSpendCard=(selector,isMonth)=>{const card=target.querySelector(selector);if(card){const toggle=()=>{if(isMonth)showMonthSpend=!showMonthSpend;else showCategorySpend=!showCategorySpend;renderView('overview')};card.addEventListener('click',toggle);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})}};bindSpendCard('[data-spend-breakdown]',false);bindSpendCard('[data-month-spend-breakdown]',true)}
document.addEventListener('click',e=>{const alertButton=e.target.closest('.dashboard-alert-banner[data-view]');if(!alertButton)return;e.preventDefault();e.stopImmediatePropagation();renderView(alertButton.dataset.view)},true);
$('viewContent').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b&&$('viewContent').contains(b)){renderView(b.dataset.view)}});
$('viewContent').addEventListener('input',e=>{if(e.target.matches('#activitySearch'))activityRowsHtml()});
$('viewContent').addEventListener('change',e=>{if(e.target.matches('#activityKind,#activityAccount,#activityFrom,#activityTo'))activityRowsHtml()});
$('viewContent').addEventListener('click',e=>{if(e.target.closest('[data-action="logout"]')){signOut();return}const deleteButton=e.target.closest('.delete[data-id]');if(deleteButton){const id=deleteButton.dataset.id;if(confirm('Delete this ledger entry?'))api('/api/ledger?id='+encodeURIComponent(id),{method:'DELETE'}).then(async()=>{await loadDashboard();renderView(activeView)}).catch(err=>{$('globalMsg').textContent=err.message});return}const quickKind=e.target.closest('[data-activity-kind]');if(quickKind){const kind=quickKind.dataset.activityKind;const select=$('activityKind');if(select)select.value=kind;document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b===quickKind));activityRowsHtml();return}const datePreset=e.target.closest('[data-activity-date]');if(datePreset){const v=datePreset.dataset.activityDate;const to=new Date();const from=new Date();if(v==='today'){from.setHours(0,0,0,0)}else if(v==='7'||v==='30'){from.setDate(from.getDate()-Number(v)+1)}else from.setTime(0);const f=$('activityFrom'),t=$('activityTo');if(f)f.value=v==='all'?'':from.toISOString().slice(0,10);if(t)t.value=v==='all'?'':to.toISOString().slice(0,10);datePreset.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===datePreset));activityRowsHtml();return}if(e.target.closest('#activityFilterToggle')){const panel=$('activityAdvancedFilters'),btn=$('activityFilterToggle');if(panel){panel.open=!panel.open;btn?.setAttribute('aria-expanded',String(panel.open))}return}if(e.target.closest('#activityApply')){const panel=$('activityAdvancedFilters');if(panel)panel.open=false;$('activityFilterToggle')?.setAttribute('aria-expanded','false');activityRowsHtml();return}if(e.target.closest('[data-clear-filter]')){const id=e.target.closest('[data-clear-filter]').dataset.clearFilter;if(id==='activityDate'){['activityFrom','activityTo'].forEach(k=>{if($(k))$(k).value=''})}else if($(id))$(id).value=id==='activityKind'?'all':'';activityRowsHtml();return}if(e.target.closest('#activityClearAll')||e.target.closest('#activityReset')){['activitySearch','activityFrom','activityTo'].forEach(id=>{if($(id))$(id).value=''});['activityKind','activityAccount'].forEach(id=>{if($(id))$(id).value='all'});document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b.dataset.activityKind==='all'));const panel=$('activityAdvancedFilters');if(panel)panel.open=false;$('activityFilterToggle')?.setAttribute('aria-expanded','false');activityRowsHtml();return}if(e.target.closest('[data-angel-refresh]')){loadAngelOne();return}if(e.target.closest('[data-stock-advisor-refresh]')){loadStockAdvisor();return}const point=e.target.closest('[data-chart-point]');if(point){const box=point.closest('.chart-interactive');if(box){box.querySelectorAll('.chart-point').forEach(p=>p.classList.remove('selected'));point.classList.add('selected');const tip=box.querySelector('.chart-tooltip');if(tip){tip.innerHTML='<b>'+point.dataset.chartValue+'</b><span>'+point.dataset.chartLabel+'</span>';tip.hidden=false;}}return}const paid=e.target.closest('[data-bill-paid]');if(paid){const id=paid.dataset.billPaid;api('/api/planned-bills',{method:'PATCH',body:JSON.stringify({id,status:'paid'})}).then(()=>{plannedBills=plannedBills.filter(b=>b.id!==id);renderView(activeView)}).catch(err=>{$('globalMsg').textContent=err.message});return}if(e.target.closest('[data-spend-close]')){showCategorySpend=false;showMonthSpend=false;renderView('overview');return}const card=e.target.closest('[data-bank]');if(card){openBank(card.dataset.bank);return}if(e.target.closest('#backToBanks'))renderView('banks')});
$('menuNav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)renderView(b.dataset.view)});
$('mobileNav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)renderView(b.dataset.view)});

async function signOut(){try{await api('/api/auth?action=logout',{method:'POST',body:'{}'});}finally{location.reload()}}
$('cancel').onclick=()=>$('txForm').classList.add('hidden');
$('txForm').onsubmit=async e=>{e.preventDefault();$('txMsg').textContent='';try{await api('/api/ledger',{method:'POST',body:JSON.stringify({kind:$('kind').value,amount:$('amount').value,category:$('category').value,account:$('account').value,date:$('date').value,description:$('description').value})});e.target.reset();$('txForm').classList.add('hidden');await load();renderView(activeView)}catch(x){$('txMsg').textContent=x.message}};
(async()=>{try{const d=await api('/api/auth');if(d.user){user=d.user;await showApp()}else{$('auth').classList.remove('hidden')}}catch(e){$('auth').classList.remove('hidden');$('globalMsg').textContent='Account verification failed: '+(e?.message||'Please try again.');console.error('[wealth-startup:auth]',e)}})();

